old='''  if(e.slowTimer>0)e.slowTimer-=dt;\n  if((battle.woolTraps||[]).some(z=>z.life>0&&Math.hypot(e.x-z.x,e.y-z.y)<=z.r))speed*=.50;\n      if((e.slothSlowTimer||0)>0){e.slothSlowTimer=Math.max(0,e.slothSlowTimer-dt);speed*=.70;}\n      if((e.cricketSlowTimer||0)>0){e.cricketSlowTimer=Math.max(0,e.cricketSlowTimer-dt);speed*=.70;}\n    if((e.snailVulnerableTimer||0)>0)e.snailVulnerableTimer=Math.max(0,e.snailVulnerableTimer-dt);\n    if((e.crowSlowTimer||0)>0){e.crowSlowTimer=Math.max(0,e.crowSlowTimer-dt);speed*=.75;}\n    if((e.gooseSlowTimer||0)>0){e.gooseSlowTimer=Math.max(0,e.gooseSlowTimer-dt);speed*=.85;}\n    if((e.zebraSlowTimer||0)>0)e.zebraSlowTimer=Math.max(0,e.zebraSlowTimer-dt);\n  if((e.chickenSlowTimer||0)>0)e.chickenSlowTimer=Math.max(0,e.chickenSlowTimer-dt);\n  if((e.goatConfuseTimer||0)>0)e.goatConfuseTimer=Math.max(0,e.goatConfuseTimer-dt);\n  if(e.hp<=0){killEnemy(e);return}\n  if((e.freezeTimer||0)>0){\n    e.freezeTimer=Math.max(0,e.freezeTimer-dt);\n    return;\n  }\n  let mult=e.slowTimer>0?.55:(e.chickenSlowTimer||0)>0?.80:(e.zebraSlowTimer||0)>0?.75:(e.goatConfuseTimer||0)>0?.50:1, dist=e.speed*mult*dt;'''
new='''  // RECENT_SLOW_CRASH_FIX_V1: tower slows must affect this enemy only, never the global game speed.\n  if(e.slowTimer>0)e.slowTimer-=dt;\n  const inWoolTrap=(battle.woolTraps||[]).some(z=>z.life>0&&Math.hypot(e.x-z.x,e.y-z.y)<=z.r);\n  if((e.slothSlowTimer||0)>0)e.slothSlowTimer=Math.max(0,e.slothSlowTimer-dt);\n  if((e.cricketSlowTimer||0)>0)e.cricketSlowTimer=Math.max(0,e.cricketSlowTimer-dt);\n  if((e.snailVulnerableTimer||0)>0)e.snailVulnerableTimer=Math.max(0,e.snailVulnerableTimer-dt);\n  if((e.crowSlowTimer||0)>0)e.crowSlowTimer=Math.max(0,e.crowSlowTimer-dt);\n  if((e.gooseSlowTimer||0)>0)e.gooseSlowTimer=Math.max(0,e.gooseSlowTimer-dt);\n  if((e.zebraSlowTimer||0)>0)e.zebraSlowTimer=Math.max(0,e.zebraSlowTimer-dt);\n  if((e.chickenSlowTimer||0)>0)e.chickenSlowTimer=Math.max(0,e.chickenSlowTimer-dt);\n  if((e.goatConfuseTimer||0)>0)e.goatConfuseTimer=Math.max(0,e.goatConfuseTimer-dt);\n  if(e.hp<=0){killEnemy(e);return}\n  if((e.freezeTimer||0)>0){\n    e.freezeTimer=Math.max(0,e.freezeTimer-dt);\n    return;\n  }\n  let mult=e.slowTimer>0?.55:inWoolTrap?.50:(e.slothSlowTimer||0)>0?.70:(e.cricketSlowTimer||0)>0?.70:(e.crowSlowTimer||0)>0?.75:(e.gooseSlowTimer||0)>0?.85:(e.chickenSlowTimer||0)>0?.80:(e.zebraSlowTimer||0)>0?.75:(e.goatConfuseTimer||0)>0?.50:1, dist=e.speed*mult*dt;'''
